INSERT INTO wiki_entries (id, slug, label, relation_icon_svg, summary, intro, entry_type, tags_json, visibility, sort_order, published_at, updated_at) VALUES ('WIKI-CHR-VS', 'vincent-skank', 'Vincent Skank', NULL, 'Vincent is Texaria''s Regional Director of the Regional Interference Field & Tactics (RIFT) Agency, overseeing all mercenary operations across the province''s districts. He''s known for his blunt, unforgiving leadership style and complete lack of subtlety.', '<strong>Vincent</strong> is [Texaria](/wiki/texaria)''s Regional Director of the [Regional Interference Field & Tactics (RIFT) Agency](/wiki/rift), overseeing all mercenary operations across the province''s districts. He''s known for his blunt, unforgiving leadership style and complete lack of subtlety. Vincent doesn''t hide his opinions, even when they''re insulting, and he expects everyone around him to follow orders without hesitation. His presence is intimidating not because he''s theatrical, but because he''s direct, literal, and unapologetically harsh.', 'Character', '[]', 'both', 14, '2026-04-20T10:59:38.741Z', CURRENT_TIMESTAMP);
