INSERT INTO wiki_entries (id, slug, label, relation_icon_svg, summary, intro, entry_type, tags_json, visibility, sort_order, published_at, updated_at) VALUES ('WIKI-CHR-TD', 'tycho-draven', 'Tycho Draven', NULL, '', '', 'Character', '[]', 'none', 19, '2026-04-20T11:01:52.961Z', CURRENT_TIMESTAMP);
INSERT INTO wiki_entries (id, slug, label, relation_icon_svg, summary, intro, entry_type, tags_json, visibility, sort_order, published_at, updated_at) VALUES ('WIKI-CHR-MA', 'marx-armstrong', 'Marx Armstrong', NULL, 'Marx is a canary and commercial pilot, known for his unwavering love of aviation and equally unshakable dedication to rules.', '<strong>Marx</strong> is a canary and commercial pilot, known for his unwavering love of aviation and equally unshakable dedication to rules. Growing up, Marx''s fascination with flying turned into both a passion and a career, but his personality remained defined by a strict sense of order. To friends, he can seem stiff or overly literal, but beneath that obedience lies someone deeply passionate about skies. Whether rattling off obscure military aircraft trivia or critiquing the smallest deviation from standard procedure, Marx''s life revolves around structure, safety, and the comfort of knowing everything is in its right place.', 'Character', '["marx-armstrong","canary","bird","redrift"]', 'both', 20, '2026-04-20T11:02:10.478Z', CURRENT_TIMESTAMP);
INSERT INTO wiki_entries (id, slug, label, relation_icon_svg, summary, intro, entry_type, tags_json, visibility, sort_order, published_at, updated_at) VALUES ('WIKI-LCT-AT', 'ambertrail', 'AmberTrail', 'AmberTrail is a suburb located in the northwestern part of San Bandera, Texaria. It is a suburban area inspired by Helotes, TX. Traditionally old-fashioned, but currently undergoing modernization.', '', '<strong>AmberTrail</strong> is a suburb located in the northwestern part of [San Bandera](/wiki/san-bandera), [Texaria](/wiki/texaria). It is a suburban area inspired by [Helotes, TX](https://en.wikipedia.org/wiki/Helotes,_Texas). Traditionally old-fashioned, but currently undergoing modernization.', 'Location', '[]', 'none', 22, '2026-04-20T11:03:17.028Z', CURRENT_TIMESTAMP);
INSERT INTO wiki_entries (id, slug, label, relation_icon_svg, summary, intro, entry_type, tags_json, visibility, sort_order, published_at, updated_at) VALUES ('WIKI-LCT-AF', 'ashford', 'Ashford', NULL, 'Ashford is a town located north of San Bandera, Texaria. It''s a smaller town known more for its outskirts than its central area due to paranormal activity.', '<strong>Ashford</strong> is a town located north of [San Bandera](/wiki/san-bandera), [Texaria](/wiki/texaria). It''s a smaller town known more for its outskirts than its central area due to paranormal activity.', 'Location', '[]', 'none', 23, '2026-04-20T11:03:53.593Z', CURRENT_TIMESTAMP);
INSERT INTO wiki_entries (id, slug, label, relation_icon_svg, summary, intro, entry_type, tags_json, visibility, sort_order, published_at, updated_at) VALUES ('WIKI-LCT-A', 'austyn', 'Austyn', NULL, 'Austyn is the capital city of Texaria, located in the central part of the province. It''s known for its vibrant culture, music scene, and growing tech industry. Austyn serves as a major hub for commerce, government, and entertainment within Texaria.', '<strong>Austyn</strong> is the capital city of [Texaria](/wiki/texaria), located in the central part of the province. It''s known for its vibrant culture, music scene, and growing tech industry. Austyn serves as a major hub for commerce, government, and entertainment within Texaria.', 'Location', '[]', 'none', 24, '2026-04-20T11:04:11.265Z', CURRENT_TIMESTAMP);
INSERT INTO wiki_entries (id, slug, label, relation_icon_svg, summary, intro, entry_type, tags_json, visibility, sort_order, published_at, updated_at) VALUES ('WIKI-LCT-CL', 'crossline', 'CrossLine', NULL, 'CrossLine is a suburb located in the northwestern part of San Bandera, Texaria. It is split between East and West by a major freeway. The East side is retail-focused with a struggling mall containing hidden gems, while the West side is automotive-heavy with repair shops and industrial businesses.', '<strong>CrossLine</strong> is a suburb located in the northwestern part of [San Bandera](/wiki/san-bandera), [Texaria](/wiki/texaria). It is split between East and West by a major freeway. The East side is retail-focused with a struggling mall containing hidden gems, while the West side is automotive-heavy with repair shops and industrial businesses.', 'Location', '[]', 'none', 25, '2026-04-20T11:04:33.940Z', CURRENT_TIMESTAMP);
INSERT INTO wiki_entries (id, slug, label, relation_icon_svg, summary, intro, entry_type, tags_json, visibility, sort_order, published_at, updated_at) VALUES ('WIKI-LCT-EV', 'eastunder-valley', 'EastUnder Valley', NULL, 'EastUnder Valley is a suburb located in the southeastern part of San Bandera, Texaria. It''s calm and unamusing during the day, but significantly dangerous at night.', '<strong>EastUnder Valley</strong> is a suburb located in the southeastern part of [San Bandera](/wiki/san-bandera), [Texaria](/wiki-texaria). It''s calm and unamusing during the day, but significantly dangerous at night.', 'Location', '[]', 'none', 26, '2026-04-20T11:05:37.205Z', CURRENT_TIMESTAMP);
INSERT INTO wiki_entries (id, slug, label, relation_icon_svg, summary, intro, entry_type, tags_json, visibility, sort_order, published_at, updated_at) VALUES ('WIKI-LCT-K', 'kallas', 'Kallas', NULL, 'Kallas is a large metropolitan city in Texaria, representing a major economic and urban hub. It draws inspiration from the Dallas–Fort Worth metropolitan area in Texas, known for its diverse economy, cultural attractions, and sprawling urban landscape.', '<strong>Kallas</strong> is a large metropolitan city in [Texaria](/wiki/texaria), representing a major economic and urban hub. It draws inspiration from the [Dallas–Fort Worth metropolitan area in Texas](https://en.wikipedia.org/wiki/Dallas%E2%80%93Fort_Worth_metropolitan_area), known for its diverse economy, cultural attractions, and sprawling urban landscape.', 'Location', '[]', 'none', 27, '2026-04-20T11:06:00.063Z', CURRENT_TIMESTAMP);
INSERT INTO wiki_entries (id, slug, label, relation_icon_svg, summary, intro, entry_type, tags_json, visibility, sort_order, published_at, updated_at) VALUES ('WIKI-LCT-NP', 'northpoint', 'NorthPoint', NULL, 'NorthPoint is a wealthy district known for its polished appearance and underlying pretentious social culture.', 'NorthPoint is a wealthy district known for its polished appearance and underlying pretentious social culture.', 'Location', '[]', 'none', 28, '2026-04-20T11:06:23.995Z', CURRENT_TIMESTAMP);
INSERT INTO wiki_entries (id, slug, label, relation_icon_svg, summary, intro, entry_type, tags_json, visibility, sort_order, published_at, updated_at) VALUES ('WIKI-LCT-SB', 'san-bandera', 'San Bandera', NULL, 'San Bandera is a major city in Bandera County, Texaria, known for its cultural heritage and historical significance. It draws inspiration from San Antonio, TX, and serves as a central hub for the surrounding suburbs and towns.', '<strong>San Bandera</strong> is a major city in Bandera County, [Texaria](/wiki/texaria), known for its cultural heritage and historical significance. It draws inspiration from [San Antonio, TX](https://en.wikipedia.org/wiki/San_Antonio), and serves as a central hub for the surrounding suburbs and towns.', 'Character', '[]', 'none', 29, '2026-04-20T11:06:39.744Z', CURRENT_TIMESTAMP);
INSERT INTO wiki_entries (id, slug, label, relation_icon_svg, summary, intro, entry_type, tags_json, visibility, sort_order, published_at, updated_at) VALUES ('WIKI-LCT-SP', 'southport', 'SouthPort', NULL, 'SouthPort is an old industrial district filled with abandoned harbor infrastructure. It is practically abandoned due to its impractical location and economic decline. It draws inspiration from the south side of San Antonio, TX, mixed with Port Aransas, TX.', '<strong>SouthPort</strong> is an old industrial district filled with abandoned harbor infrastructure. It is practically abandoned due to its impractical location and economic decline. It draws inspiration from the south side of [San Antonio, TX](https://en.wikipedia.org/wiki/San_Antonio), mixed with [Port Aransas, TX](https://en.wikipedia.org/wiki/Port_Aransas,_Texas).', 'Location', '[]', 'none', 30, '2026-04-20T11:06:59.421Z', CURRENT_TIMESTAMP);
INSERT INTO wiki_entries (id, slug, label, relation_icon_svg, summary, intro, entry_type, tags_json, visibility, sort_order, published_at, updated_at) VALUES ('WIKI-LCT-TX', 'texaria', 'Texaria', NULL, 'Texaria is a province in the United Provinces of Avalona, known for its diverse landscapes, rich culture, and significant economic influence. It draws heavy inspiration from the state of Texas in the United States, incorporating elements of its geography, culture, and history into the world of Avalona.', '<strong>Texaria</strong> is a province in the [United Provinces of Avalona](/wiki/upa), known for its diverse landscapes, rich culture, and significant economic influence. It draws heavy inspiration from the state of [Texas](https://en.wikipedia.org/wiki/Texas) in the [United States](https://en.wikipedia.org/wiki/United_States), incorporating elements of its geography, culture, and history into the world of Avalona.', 'Location', '[]', 'none', 31, '2026-04-20T11:07:32.020Z', CURRENT_TIMESTAMP);
INSERT INTO wiki_entries (id, slug, label, relation_icon_svg, summary, intro, entry_type, tags_json, visibility, sort_order, published_at, updated_at) VALUES ('WIKI-LCT-UP', 'upa', 'United Provinces of Avalona', NULL, 'United Provinces of Avalona is the largest and most populous country in Avalona, encompassing a vast and diverse range of landscapes, cultures, and climates. It serves as the primary setting for many of the events in the world of Avalona and is home to a wide variety of characters, locations, and stories. The country draws heavy inspiration from the United States, incorporating elements of its geography, culture, and history into the world of Avalona.', 'The <strong>United Provinces of Avalona</strong> is the largest and most populous country in North Avalona, encompassing a vast and diverse range of landscapes, cultures, and climates. It serves as the primary setting for many of the events in the world of [REDRIFT](/wiki/redrift) and is home to a wide variety of characters, locations, and stories. The country draws heavy inspiration from the [United States](https://en.wikipedia.org/wiki/United_States), incorporating elements of its geography, culture, and history into the world of REDRIFT.', 'Location', '[]', 'none', 32, '2026-04-20T11:08:02.480Z', CURRENT_TIMESTAMP);
INSERT INTO wiki_entries (id, slug, label, relation_icon_svg, summary, intro, entry_type, tags_json, visibility, sort_order, published_at, updated_at) VALUES ('WIKI-BUS-LC', 'larries', 'Larrie''s Chicken Fingers', NULL, 'Larrie''s Chicken Fingers is a popular fast-food chain specializing in chicken fingers, known for its signature sauce and casual dining experience. Founded by Larrie Caine, the chain has expanded across multiple locations, becoming a beloved spot for quick and tasty meals.', '<strong>Larrie''s Chicken Fingers</strong> is a popular fast-food chain specializing in chicken fingers, known for its signature sauce and casual dining experience. Founded by [Larrie Caine](/wiki/larrie-caine), the chain has expanded across multiple locations, becoming a beloved spot for quick and tasty meals.', 'Business', '[]', 'none', 33, '2026-04-20T11:08:28.559Z', CURRENT_TIMESTAMP);
INSERT INTO wiki_entries (id, slug, label, relation_icon_svg, summary, intro, entry_type, tags_json, visibility, sort_order, published_at, updated_at) VALUES ('WIKI-BUS-PB', 'pearbys', 'Pearby''s', NULL, 'Pearby''s is a restaurant chain known for its casual dining experience and Avalonian cuisine. Founded by William and J.T. Pawmer, Pearby''s has become a popular destination for locals and visitors alike, offering a diverse menu that celebrates the flavors of Avalona.', '<strong>Pearby''s</strong> is a restaurant chain known for its casual dining experience and Avalonian cuisine. Founded by [William](/wiki/william-pawmer) and [J.T. Pawmer](/wiki/jt-pawmer), Pearby''s has become a popular destination for locals and visitors alike, offering a diverse menu that celebrates the flavors of [Avalona](/wiki/upa).', 'Business', '[]', 'none', 34, '2026-04-20T11:09:12.815Z', CURRENT_TIMESTAMP);
INSERT INTO wiki_entries (id, slug, label, relation_icon_svg, summary, intro, entry_type, tags_json, visibility, sort_order, published_at, updated_at) VALUES ('WIKI-ORG-APS', 'aps', 'Ashford Paranormal Society', NULL, 'Ashford Paranormal Society is a small group of paranormal investigators based in Ashford, Texaria. They are known for their investigations into local hauntings and supernatural occurrences, often sharing their findings with the public through various media channels. The society draws inspiration from the Bythorne Paranormal Society from popular web series The Mandela Catalogue, incorporating elements of their investigative approach and storytelling style into their own work.', '<strong>Ashford Paranormal Society</strong> is a small group of paranormal investigators based in [Ashford](/wiki/ashford), [Texaria](/wiki/texaria). They are known for their investigations into local hauntings and supernatural occurrences, often sharing their findings with the public through various media channels. The society draws inspiration from the [Bythorne Paranormal Society](https://mandela-catalogue.fandom.com/wiki/Bythorne_Paranormal_Society) from popular web series [The Mandela Catalogue](https://en.wikipedia.org/wiki/The_Mandela_Catalogue), incorporating elements of their investigative approach and storytelling style into their own work.', 'Character', '[]', 'none', 35, '2026-04-20T11:09:34.646Z', CURRENT_TIMESTAMP);
