INSERT INTO wiki_quotes (entry_id, quote_text, audio_url, attribution, voice_credit, nsfw_only) VALUES ('WIKI-CHR-JSD', 'I can feel you breathing from here. I could totally make this worse.~', NULL, 'Jesper', NULL, 1);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-JSD-APRC', 'WIKI-CHR-JSD', 'appearance', 'Appearance', replace('He’s a lot bigger now. Taller, heavier, softer. Not necessarily muscle, either.\n\nThere’s a red section across his belly that didn’t heal right after the change. It stretches more than it should and has a bright orange outline running along it and down his tail. It’s a weird texture, not quite skin.\n\nThe wings are small, bony, and don’t really work. They just hang there. The skull isn’t something he wears anymore. It’s part of his face now, with those sharp horns angling back.\n\nHe still has the heterochromia; however, the yellow eye isn''t just an outline. They stand out more now, even when half-lidded most of the time.','\n',char(10)), 'markdown', 1, 0);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-JSD-PRSN', 'WIKI-CHR-JSD', 'personality', 'Personality', replace('He spaces out a lot. Just stands there sometimes like he forgot what he was doing.\n\nHe’s not as openly aggressive, but that doesn’t make him easier to deal with. He’ll lean in too close, say something that sounds playful, and just… stay there. No follow-up. You’re the one left deciding if that was a joke.\n\nThere’s also this weird, slightly dumb edge to him now. Not completely gone, just… off by a bit. Like something in his head got scrambled and never fully settled back.','\n',char(10)), 'markdown', 1, 1);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-JSD-HSTR', 'WIKI-CHR-JSD', 'history', 'History', replace('He put on the wrong mask one morning.\n\nThat’s it.\n\nAfter that, everything changed and didn’t change at the same time. He remembers who he was, he just doesn’t feel connected to it anymore. He stopped sticking to agency work and started doing things on his own terms.','\n',char(10)), 'markdown', 1, 2);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-JSD-ABLT', 'WIKI-CHR-JSD', 'abilities', 'Abilities', 'TODO', 'markdown', 1, 3);
