INSERT INTO wiki_quotes (entry_id, quote_text, audio_url, attribution, voice_credit, nsfw_only) VALUES ('WIKI-CHR-ZH', 'You''d be surprised what kind of damage I can do just by leaning forward.', 'https://media.raccstarlogan.com/wiki/assets/char/zh/q.mp3', 'Zeke', 'voiced by [RoyalFoil](https://www.castingcall.club/royal_foil01)', 0);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-ZH-APRC', 'WIKI-CHR-ZH', 'appearance', 'Appearance', replace('Zeke is a heavyset shark with a wide, solid frame shaped by years of physical work followed by years of unapologetic comfort. His middle is round and soft, his shoulders broad, and his limbs thick and steady. Stretch marks trace along his sides and stomach, subtle but noticeable up close.\n\nHis coloration leans cool gray with a faint blue undertone, depending in shadow. Dark stripes cut across his arms and tail in uneven, jagged patterns. His hair is black with a slight blue sheen, and the lighter tones along his belly and inner arms soften the overall look without standing out.\n\nHe dresses for ease rather than style. Most days he wears an old tank top that''s been stretched and sun-faded from years on the docks, paired with brown cargo shorts that can handle whatever he stuffs into the pockets. A golden key pendant hangs from his neck, something he keeps close but rarely talks about.\n\nZeke moves with a relaxed confidence. His weight sits mostly around his middle, giving him a rounded silhouette, but he carries himself like someone who knows exactly how much space he takes up and doesn''t mind it. His posture is loose, his steps unhurried, and his presence steady enough to make people notice him even when he''s trying not to.','\n',char(10)), 'markdown', 0, 0);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-ZH-PRSN', 'WIKI-CHR-ZH', 'personality', 'Personality', replace('Zeke is the quieter half of the Skank twins. Jason chases attention; Zeke lets it come to him. He speaks in a slow, confident drawl, often with a smirk that suggests he''s already decided how the conversation will end.\n\nHe enjoys teasing people, especially when he can get a reaction without raising his voice. Despite the sharp tongue, he''s approachable and patient, especially with friends and anyone who isn''t trying too hard to impress him. He''s hard to rattle, hard to rush, and harder to read, which is a combo that makes him strangely magnetic in social settings.','\n',char(10)), 'markdown', 0, 1);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-ZH-HSTR', 'WIKI-CHR-ZH', 'history', 'History', replace('Zeke grew up in SouthPort with his twin brother Jason, though the two rarely seemed alike. Jason wanted eyes on him at all times; Zeke preferred being the dependable one people quietly relied on. Teachers and coaches often gravitated toward Zeke''s steadiness, something Jason never quite understood.\n\nAfter finishing school, Zeke joined harbor security and quickly earned a reputation for being reliable, strong, and level-headed. He didn''t brag about the job, but he took it seriously. That reputation held until a dock accident changed the way he moved. A snapped hoist line sent a crate swinging into him, knocking him off balance and leaving him with a hip injury that never healed the way the doctors promised.\n\nInstead of slowing down, Zeke pushed through it, a stubborn Skank-family habit he never quite escaped. The more he worked, the worse the joint became, and the gradual weight he put on only made the strain harder to ignore. He kept insisting he was fine long after everyone else could see he wasn''t. Patrols took longer, stairs felt steeper, and the uneven concrete along the docks turned every shift into a quiet battle he refused to acknowledge.\n\nHe met Aziran during this slow decline. What started as a routine patrol (and a warning to an artist sketching where he shouldn''t be) turned into a conversation that stuck with both of them. Azrian didn''t care about Zeke''s reputation or his physical presence; he cared about the person underneath. Their quiet evenings and shared meals didn''t necessarily cause Zeke''s retirement, but they made it easier for him to finally admit he couldn''t keep pushing himself the way he used to.\n\nBy the time he stepped away from harbor security, the decision wasn''t dramatic. It was simply the point where his body and his life both told him it was time to stop.','\n',char(10)), 'markdown', 0, 2);
