INSERT INTO wiki_quotes (entry_id, quote_text, audio_url, attribution, voice_credit, nsfw_only) VALUES ('WIKI-CHR-AH', '... You *sure* that''s how it''s supposed to work?', NULL, 'Azrian', NULL, 0);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-AH-APRC', 'WIKI-CHR-AH', 'appearance', 'Appearance', replace('Azrian''s wardrobe is simple and practical. He almost always wears durable blue overalls, patched from years of work and usually rulled down or clipped loose when he''s off duty. Shirts are optional unless the weather demands it. He dresses for comfort and utility, not style, and he''s long since stopped pretending otherwise.\n\nHis skin is a deep aquamarine that fades into a gray underbelly running from his chin down his torso. The gradients along his arms, back, and tail deepen in the low light, giving him a smooth understated palette that contrasts with his bioluminescent features. His eyes, lure, and fin edges glow in cyan-teal tones, bright enough to stand out but soft enough to not overwhelm.\n\nAzzy isn''t thin - years of taste-testing his own cooking and keeping snacks on hand have given him a rounder, softer build. He''s not nearly as large as his husband, but he''s comfortably heavyset in a way that suits his lifestyle. His weight isn''t a spectacle; it''s simply a part of who he is, shaped by long nights, good meals, and a habit of feeding others as much as himself.\n\nTwo short, ragged horn-like fins rise from his forehead, subtle enough not to dominate his silhouette but distinct enough to frame his face. They match his skin tone and bend naturally into his design.','\n',char(10)), 'markdown', 0, 0);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-AH-PRSN', 'WIKI-CHR-AH', 'personality', 'Personality', replace('Azzy keeps a quiet, steady presence that makes him easy to underestimate. He isn''t loud or attention-seeking, and most people know him as reserved, thoughtful, and a little difficult to read. He doesn''t open up quickly, preferring silence over small talk until he has something worth saying.\n\nOnce he relaxes, a warmer side comes through. He has a subtle teasing streak - subtle, dry, and perfectly timed. He enjoys small comforts like cooking, late-night walks, collecting odd maritime trinkets, and listening to old radio shows while he works. He shows care through actions rather than words, often in ways people don''t notice until later.\n\nAzrian avoids conflict and rarely raises his voice, but he isn''t passive. When something matters to him, he holds firm. His patience makes him good at handling long hours, tedious tasks, and stubborn people. There''s a grounding quality to him, a sense that he sees more than he lets on and chooses carefully what he shares.','\n',char(10)), 'markdown', 0, 1);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-AH-BHCD', 'WIKI-CHR-AH', 'behind-closed-doors', 'Behind Closed Doors', replace('Azzy''s affection shows itself in ways that are impossible to mistake once you see them. He doesn''t just enjoy Zeke''s size; he actively embraces and feeds into it. Cooking meals WAY bigger than necessary, always making sure food is close by, slipping in extra portions without comment... These aren''t accidents. He actively encourages Zeke to indulge, sometimes teasingly, sometimes with a quiet push, but always with the intent of seeing him satisfied and heavier than before.\n\nWhat might look like simple spoiling from the outside is deliberate on Azzy''s part. He takes pride in being the one who keeps Zeke full and then some, and in knowing his efforts show over time. It''s not framed as a joke or a passing quirk, it''s just how he loves.\n\nFor Azzy, there''s a quiet satisfaction in this ritual. Watching Zeke soften, noticing shirts fit tighter, or seeing the way he sinks a little deeper into a chair, these are things Azzy quietly treasures. They''re signs that his care is working, that his presence leaves a mark. It''s a slow, ongoing process that he takes pride in, and it''s a core part of how he expresses love. Each added pound feels like proof of his devotion: something visible, tangible, and deeply personal. Zeke himself doesn''t always acknowledge the changes, but when he does, it''s usually just a smirk. However, sometimes, it''s a tug at his shirt to emphasize the stretch, a deliberate lean into Azzy that leaves no room to ignore it. Those moments always fluster him, though he hides it poorly, and Zeke, of course, knows *exactly* what he''s doing.','\n',char(10)), 'markdown', 1, 2);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-AH-HSTR', 'WIKI-CHR-AH', 'history', 'History', replace('Azrian grew up in SouthPort and spent most of his life near the harbor, where work was steady and quiet. He built a reputation as someone who could fix what others left broken, like machinery, infrastructure, or the odd problem nobody else wanted to deal with. He found comfort in late-night shifts, tide charts, and the quiet rhythm of maintenance work. While others saw harbor upkeep as thankless, Azzy valued the solitude and the freedom it gave him.\n\nFor years, he kept to himself. He wasn''t unfriendly, but he deflected personal questions with humor or silence, keeping people at arm''s length. That changed when he crossed paths with Zeke during a routine harbor patrol. Azzy had wandered into an off-limits dockyard to sketch under poor lighting and nearly earned himself a write-up. Instead, the awkward warning turned into a conversation that neither expected. Zeke''s grounded presence and straightforward nature drew Azzy out of his shell in a way nobody else had. Small talk became shared coffee, then regular meetups, then something deeper. Their bond grew steadily, and marriage followed.\n\nAzzy''d world didn''t stay small. During one of his late night walks (the kind he took when the harbor was quiet and the air felt clean) he stumbled across a library he didn''t quite remember being there. It wasn''t on any map, and the building looked older than the street around it. Curiosity won out, and he stepped inside.\n\nThat''s where he met Judas.\n\nMost people would''ve been intimidated by a shadowy almost-eight-foot-tall dragon with glowing purple eyes standing alone in an abandoned library that seemed to exist in more places than one. Azzy wasn''t. He treated Jude the same way he treated everyone else: calm, polite, and quietly observant. Jude expected fear; Azzy offered conversation. That was enough to start something.\n\nOver time, Azrian started showing up at the library often enough that Judas stopped reacting to it. He''d fix a lantern, adjust a shelf, or just sit somewhere and read without bothering anyone. Judas didn''t think of it as friendship at first, just someone who didn''t disrupt the place, but Azzy''s presence had a way of keeping the library quiet in a good way. No pressure, no expectations, no prophecy talk unless Jude brought it up. Eventually, they realized they talked more around Azzy than anyone else, even if half of it was just dry comments or small observations. It wasn''t sentimental, it was just... easy.\n\nNow settled with his husband, Azrian still works around the harbor, but his life is shaped as much by the people he''s chosen by the work he does. He finds joy in the mundane: cooking meals, maintaining their home, and offering the kind of stability that helps Zeke slow down. And in the background, his connection with Jude remains one of the quiet pillars of his life, a friendship that matters more than most people realize.','\n',char(10)), 'markdown', 0, 3);
