INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-AH-WRTN', 'WIKI-CHR-AH', 'His handwriting is surprisingly neat, almost calligraphic, despite his otherwise rough, practical nature.', 0, 0);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-AH-RDIO', 'WIKI-CHR-AH', 'He has a quiet fondness for late-night radio shows and sometimes leaves them playing softly while he works.', 0, 1);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-AH-LTRN', 'WIKI-CHR-AH', 'Though he dislikes bright artificial lighting, he owns several lanterns and candles, claiming they "make the dark feel friendlier."', 0, 2);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-AH-SKCH', 'WIKI-CHR-AH', 'He rarely finishes a sketchbook, often abandoning it halfway once he feels it''s "served its purpose."', 0, 3);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-AH-MURL', 'WIKI-CHR-AH', 'Azzy painted a mural of Zeke near his old station around the time of his retirement, leaving a quiet tribute to his work, despite being short-lived.', 0, 4);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-AH-COOK', 'WIKI-CHR-AH', 'He claims he "cooks too much by accident," though anyone close to him knows it isn''t really an accident.', 0, 5);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-AH-MTWG', 'WIKI-CHR-AH', 'At one point he had a phase where he tried gaining weight himself, alongside Zeke, but he stopped after realizing that it just wasn''t for him.', 1, 6);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-AH-AZOF', 'WIKI-CHR-AH', 'He and Zeke ran a paid subscription documenting Zeke''s weight gain, which helps fund most of the food Azrian cooks for him.', 1, 7);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-AH-GFTI', 'WIKI-CHR-AH', 'There are sometimes hidden graffiti doodles at the harbor Azzy works at that hint at him and Zeke''s future. They are promptly removed or covered up the next day.', 1, 8);
