INSERT INTO wiki_quotes (entry_id, quote_text, audio_url, attribution, voice_credit, nsfw_only) VALUES ('WIKI-CHR-JU', replace('I don''t owe you an explanation.\nYou wouldn''t believe me anyway.','\n',char(10)), 'https://media.raccstarlogan.com/wiki/assets/char/ju/q.mp3', 'Judas', 'voiced by [Constellist](https://vgen.co/constellist)', 0);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-JU-APRC', 'WIKI-CHR-JU', 'appearance', 'Appearance', replace('Judas has dark gray scales marked with black striping, giving their silhouette a sharp, angular look. Their eyes glow a vivid violet, bright enough to catch attention even in dim light. Their swept black hair carries streaks of pastel purple, matching the lavender tones in their claws and wing accents.\n\nCurved horns frame their head, and three distinct tails trail behind them, each moving with a mind of its own. Their wings are bat-like, black with purple striping along the edges. Dramatic, but not theatrical.\n\nTheir clothing leans into a practical punk look rather than anything theatrical. Jude usually wears a spiked black choker and matching bracelets, plus a dark purple vest with the sleeves torn off. Their pants are worn black and tucked into heavy boots. Nothing fancy, just durable. They also have a small cross charm hanging from one horn. It doesn''t mean anything; they just liked how it looked.\n\nTLDR; They dress like someone who doesn''t care what people think.','\n',char(10)), 'markdown', 0, 0);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-JU-PRSN', 'WIKI-CHR-JU', 'personality', 'Personality', replace('Jude is calm, deliberate, and quietly sardonic. They rarely raise their voice, preferring clipped truths and half-answers that sound like riddles even when they''re not trying to be cryptic. They keep people guessing because they''ve never properly learned how to be straightforward.\n\nThey''re not condescending out of superiority, they''re that way out of exhaustion. They''ve spent their entire existence being treated like a walking omen, and it''s worn them down. Their dry delivery often reads sharper than intended, but those who know them understand the difference.\n\nDespite their mythical background, Judas doesn''t act like a prophet. They treat their role with resignation, not reverence. They''d rather talk about music, astronomy, or weird neon signs than destiny. They enjoy late-night outings, impromptu singing, and quiet conversations with people who don''t expect them to be mystical.\n\nUnderneath the cryptic exterior is someone who wants connection but doesn''t know how to initiate it without sounding like they''re quoting prophecy.','\n',char(10)), 'markdown', 0, 1);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-JU-HSTR', 'WIKI-CHR-JU', 'history', 'History', replace('Judas was never truly "born" in the traditional sense, they simply began to exist. From their first moment of awareness, the only home they have known was the strange library they now reside in, of which the location remains a complete mystery. They grew up assuming that was normal.\n\nThey spent their early life reading everything they could reach. [REDRIFT](/wiki/redrift)''s magic is built on a linguistic system, built on forgotten languages, symbolic structures, and books containing knowledge nobody was meant to translate. Jude learned this magic the way other kids learnt handwriting: slowly, imperfectly, and with a lot of assumptions.\n\nAmong the texts was a manuscript outlining a prophecy. Jude studied it obsessively, taking notes, cross-referencing passages, and building their understanding of "what''s coming." Their notes became their guide, and they trusted them more than the original script. Not out of arrogance, but because they grew up confident that their interpretations were accurate.\n\nThey left the library briefly during college, trying to live a more normal life. They joined a band with [Xor](/wiki/xor-wulff), becoming the lead vocalist. Their performances were intense, magnetic, and a little unsettling. Behind the scenes, tensions rose. Jude''s cryptic communication clashed with the group, and their relationship with Xor strained under the weight of unspoken expectations. The band fell apart, and Jude returned to the library, not defeated, just disillusioned.\n\nSince then, Jude has drifted between the library and the outside world, offering guidance to people they believe are connected to the things they''ve studied. They''re earnest in their efforts, even if their delivery is cryptic or their timing is questionable. Jude isn''t necessarily bad or good, just someone trying to make sense of a role they never asked for, using the tools they grew up with and the notes they trust a little too much.\n\nThey''re flawed, stubborn, and occasionally misguided, but never malicious. If anything, Jude''s simply navigating the world they only way they know how: quietly, cautiously, and with the strange confidence of someone who''s spent their entire life believing they''re supposed to understand everything when they don''t.','\n',char(10)), 'markdown', 0, 2);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-JU-ABLT', 'WIKI-CHR-JU', 'abilities', 'Abilities', 'TODO', 'markdown', 0, 3);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-MO70T8HS-CLEXJ', 'WIKI-CHR-JU', 'They refuse to eat chicken if it''s not *specifically* from Larrie''s™.', 0, 0);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-MO70TOXM-FRKPI', 'WIKI-CHR-JU', 'Their magic aura glows a deep violet and leaves faint afterimages. Some say you can read things in the trails if you know what to look for', 0, 1);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-MO70U9D6-LC7BQ', 'WIKI-CHR-JU', 'Occasionally they''ll show up in people''s dreams. They say it''s accidental; it''s not.', 0, 2);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-MO70UNHE-8KXRY', 'WIKI-CHR-JU', 'They''re technically a "prophet" but insist that it''s more of a side thing.', 0, 3);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-MO70V3WN-QSS6Y', 'WIKI-CHR-JU', 'They somehow always have exact change.', 0, 4);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-MO70VB8M-U76ET', 'WIKI-CHR-JU', 'They have a surprisingly high alcohol tolerance and impeccable karaoke skills.', 0, 5);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-MO70VN14-WDJED', 'WIKI-CHR-JU', 'They have a habit of humming or singing under their breath when they think nobody''s listening.', 0, 6);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-MO70W19S-G9DM6', 'WIKI-CHR-JU', 'They treat bar trivia nights like a serious competition. They usually win.', 0, 7);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-MO70WGRZ-Z1X07', 'WIKI-CHR-JU', 'On rare nights, they''ll volunteer to run lights or effects at small shows, using magic for "visual flair" without anyone realizing it isn''t stage tech.', 0, 8);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-MO70X2ZV-I9V8H', 'WIKI-CHR-JU', 'Despite being careful with magic in serious situations, they''ve been known to use small spells purely for mischief, like flickering streetlamps or setting off automatic doors nearby.', 0, 9);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-MO70XQN5-UX9H2', 'WIKI-CHR-JU', 'Across [Avalona](/wiki/upa), bus drivers trade stories about Judas appearing on their routes. They''ll ride quietly for a few stops with no clear destination, then vanish without anyone noticing when they get on or off. Some swear the seat is empty the moment they glance back.', 0, 10);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-MSH4Y6G9-SMU1D', 'WIKI-CHR-JU', 'They don''t have any sexual genitalia, due to not being biologically born, likely a consequence of an ancestor going to town with a civilian which led to the birth of their "cousin", Wyvern.', 1, 11);
