INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-L-APRC', 'WIKI-CHR-L', 'appearance', 'Appearance', replace('im a big fat wickerbeast from the swamp im blue and i have a purple tummy with a blue line going across it people call me blueberry because im so blue and round\n\nmy claws are chunky with webs or something in between them and i also have a tail with stripes and spikes\n\ni dont really fit in any clothes so i dont wear any but i think its funny to play dress up sometimes :3\n\nlogan told me to say i slouch when i walk but idk what that means','\n',char(10)), 'markdown', 0, 0);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-L-PRSN', 'WIKI-CHR-L', 'personality', 'Personality', replace('im very silly and lazy i dont do a lot unless its fun or involves food\n\nsometimes i nap in random places and forget where i am when i wake up\n\nim very friendly! i love everyone :3 i hope i can be freinds with everyon :o','\n',char(10)), 'markdown', 0, 1);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-L-HSTR', 'WIKI-CHR-L', 'history', 'History', replace('i dont know what this is im gonna make logan write this for me\n\nLeo was created in a lab from a sample of Logan''s DNA. The reasoning behind this has since been forgotten, but I don''t remember giving them permission to use my DNA in that way. I just wanted to see if [Jesper](/wiki/jesper-foster) was indeed my brother; I guess I just clicked the checkbox allowing them to use it without actually reading into what it meant??? It''s whatever, we don''t worry about that.\n\nI''m giving this back to Leo. Hopefully he doesn''t read this section, I don''t think he''d take being an accident too well...\n\nhi its me leo again logan told me not to read that so yewah its probably sad :(','\n',char(10)), 'markdown', 0, 2);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-L-ABLT', 'WIKI-CHR-L', 'abilities', 'Abilities', replace('i can pick up heavy stuff pretty easy i think\nsometimes i break thins but its an accident :(\ni can eat a lot of food\ni can sleep anywehr\ni can hug people really good and sometimes they fall asleep on me but for some reason logan looks at me funny when i do\ni can stay still for a long time if im sleepy\ni glow a bit sometimes after blueberies but i dont no y','\n',char(10)), 'markdown', 0, 3);
