INSERT INTO wiki_quotes (entry_id, quote_text, audio_url, attribution, voice_credit, nsfw_only) VALUES ('WIKI-CHR-KF', 'Okay, take 35... rolling.', 'https://media.raccstarlogan.com/wiki/assets/char/kf/q.mp3', 'Kevin', 'voiced by Joel Butler', 0);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-KF-APRC', 'WIKI-CHR-KF', 'appearance', 'Appearance', replace('Kevin was a raccoon standing six feet tall, with a frame that leaned lanky but worn down from years of hard work behind the camera. His fur had once been bleached into a striking blonde, though by some time in his later years, it had faded unevenly, leaving washed-out streaks in his hair and beard against the natural grays and browns of his fur. Heavy-lidded hazel-green eyes and a perpetually tired expression gave him an air of someone who''d seen more long nights than good sleep.\n\nHis most recognizable outfit included a faded Rose Flow t-shirt, often layered with camo-print pants, occasionally a red-black flannel, and a pair of sandals. He was rarely without a cup of coffee in hand. His clothes weren''t exactly flashy, but they were practical and comfortable for what he did.','\n',char(10)), 'markdown', 0, 0);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-KF-PRSN', 'WIKI-CHR-KF', 'personality', 'Personality', replace('Kevin carried himself with a kind of tired charm, the sort that came from years of balancing ambition with exhaustion, as well as a family he never quite knew how to prioritize. Once confident and charismatic, years of burnout left him scattered, with a tendency to overpromise and stretch the truth. Sometimes it was just playful exaggeration, but more often than not it was a way of covering gaps he didn''t want to confront.\n\nHe was ambitious but unfocused, chasing big ideas and side projects that rarely made it past the planning stage. At home, he avoided direct confrontation, preferring to distract or defuse tension rather than face it head-on. This made him likable in short bursts but frustrating to live with long-term. Still, he wasn''t without warmth. His dry humor, casual storytelling, and unshakable interest in recording everyday life made him memorable to those around him.\n\nHis flaws often outweighed his follow-through, but he had an undeniable sincerity beneath it all. To Jesper, he was both a mystery and a constant, a father who wasn''t always steady, but who left a lasting impression. To Logan, he remained more of an absence than a presence, a figure known through stories and fragments rather than direct experience.','\n',char(10)), 'markdown', 0, 1);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-KF-HSTR', 'WIKI-CHR-KF', 'history', 'History', replace('Kevin grew up chasing the idea of creativity without ever finding a way to make it fully sustainable. His self-appointed title of "Media Director" sounded respectable, but in practice he was a cameraman and low-budget producer, often juggling underpaid gigs that left him tired but stubbornly committed. His work gave him just enough reason to stay on the road and behind the lens, documenting life even if he wasn''t asked to.\n\nAt home, his passion for filming carried into his personal life. He developed a fixation on VHS technology, not just as a medium but as an identity, recording Jesper''s childhood in detail, convinced that the tape preserved something digital never could. This habit was misunderstood by his then-wife, [Zelda](/wiki/zelda-voss), who often accused him of being invasive or obsessive. In truth, he wasn''t invasive; he was simply trying to capture and preserve moments that mattered to him.\n\nNot long after Jesper''s birth, Kevin complicated matters further. A one-night stand led to [Emily](/wiki/emily-reeves) conceiving a child, Logan, who was later born on New Years of 2005. Zelda learned of the affair pretty early on, and it only deepened the fracture between them. Kevin kept his distance, never stepping into Logan''s life in any meaningful way. Had he lived, he likely would have remained avoidant, unwilling to reconcile that part of his past. For Logan, Kevin was never a father figure, only a name and a shadow cast over circumstances beyond his control.\n\nIn the mid 2010''s, Kevin became embroiled in a bitter custody battle over Jesper with Zelda. Despite his exhaustion, his court appearances showed a rare sharpness; he fought hard to prove he could provide Jesper with stability. By December 2015, his demeanor had noticeably worn down, though his magic, subtle and largely unexplored, showed signs of improvement. The case concluded on March 1, 2016, with Kevin winning full custody.\n\nTODO: make this an accordion\nTitle: "The Accident (Content Warning: depictions of death)"\nContent: "That same day, on their way home in heavy rain, Kevin''s car hydroplaned and veered off the road into a ditch, running into oncoming traffic on the way. The impact in the ditch ruptured part of the vehicle''s fuel system, igniting in a sudden explosion. Emergency crews described the wreck as catastrophic, with little left to recover. Kevin was killed instantly, and Jesper (only JUST turning thirteen) was officially presumed dead at the scene.\n\nIn reality, Jesper had survived against all odds, but with severe injuries and immense mental trauma. The accident left him with deep scars and partial amnesia, erasing much of his life before that day. His survival went unnoticed long enough that custody reverted to no one, leaving him to grow up disconnected from his mother entirely. The only physical remnant of Kevin to endure was his skull, later becoming the mask Jesper carries into adulthood."\n\nTo Jesper, Kevin was remembered as both warmth and disappointment, a flawed father who tried, but never enough. To Logan, Kevin remains a ghost: absent from the start, and unreachable long after.','\n',char(10)), 'markdown', 0, 2);
