INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-KF-RSFL', 'WIKI-CHR-KF', 'He wore the same faded Rose Flow shirt to most of his gigs.', 0, 0);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-KF-VCML', 'WIKI-CHR-KF', 'He would tend to leave long voicemails instead of texting.', 0, 1);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-KF-LGND', 'WIKI-CHR-KF', 'Despite everything, there are a few people who still think he was some kind of legend.', 0, 2);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-KF-CFFE', 'WIKI-CHR-KF', 'His coffee cup was practically glued to his hand; he''d refill it so often that Jesper joked it was a part of him.', 0, 3);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-KF-VHST', 'WIKI-CHR-KF', 'He insisted VHS tapes had a soul that digital media could never capture, often defending the format in arguments long after it was deemed obsolete.', 0, 4);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-KF-BRKE', 'WIKI-CHR-KF', 'Even when broke, he always found ways to afford blank tapes. They were the one thing he''d never cut from his budget.', 0, 5);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-KF-HNDW', 'WIKI-CHR-KF', 'His handwriting was almost illegible, often leaving people to guess what tape labels were supposed to say.', 0, 6);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-KF-VENT', 'WIKI-CHR-KF', 'Some of his old recordings feature himself talking directly to the camera, venting frustrations he never said out loud to family or friends.', 0, 7);
INSERT INTO wiki_relationships (id, entry_id, related_entry_id, relation_label, notes, sort_order) VALUES ('WIKI-REL-KF-LF', 'WIKI-CHR-KF', 'WIKI-CHR-LF', 'Son (accidental)', 'I couldn''t be there for him. Not while having to raise Jesper, too.', 0);
INSERT INTO wiki_relationships (id, entry_id, related_entry_id, relation_label, notes, sort_order) VALUES ('WIKI-REL-KF-JF', 'WIKI-CHR-KF', 'WIKI-CHR-JF', 'Son', 'What a cute little guy.', 1);
INSERT INTO wiki_relationships (id, entry_id, related_entry_id, relation_label, notes, sort_order) VALUES ('WIKI-REL-KF-ER', 'WIKI-CHR-KF', 'WIKI-CHR-ER', 'One-Night Stand', 'I shouldn''t have even seen her. I regret everything about that day.', 2);
INSERT INTO wiki_relationships (id, entry_id, related_entry_id, relation_label, notes, sort_order) VALUES ('WIKI-REL-KF-ZV', 'WIKI-CHR-KF', 'WIKI-CHR-ZV', 'Ex-Wife', 'She was way too demanding and controlling over my son. It got even worse after... THAT day.', 3);
INSERT INTO wiki_relationships (id, entry_id, related_entry_id, relation_label, notes, sort_order) VALUES ('WIKI-REL-KF-TF', 'WIKI-CHR-KF', 'WIKI-CHR-TF', 'Brother', 'He kind of stays in his own lane. We talk, but not every day.', 4);
