INSERT INTO wiki_quotes (entry_id, quote_text, audio_url, attribution, voice_credit, nsfw_only) VALUES ('WIKI-CHR-VS', 'If anyone asks, this operation never existed. Clear?', 'https://media.raccstarlogan.com/wiki/assets/char/vs/q.mp3', 'Vincent', 'voiced by Joel Butler', 0);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-VS-APRC', 'WIKI-CHR-VS', 'appearance', 'Appearance', replace('Vincent resembles both Jason and Zeke, but with an older build shaped by years of field work followed by a long stretch of office command. He has a military buzz-cut and a scar over his right eye, leaving the sclera permanently blackened. His posture is confrontational and evaluative, and he tends to stand in ways that make people feel like they''re being judged.\n\nHis silhouette is broad and imposing, with an unintentionally bulky "muscle-gut" build that reflects strength layered over age. He moves slowly and intentionally, never wasting motion. His expression rarely changes, and when it does, it''s usually to signal disapproval.\n\nVincent typically wears dark tactical clothing suited for both command and intimidation. His usual outfit includes a maroon reinforced military jacket, heavy blue work-jeans, and black steel-toe boots. ','\n',char(10)), 'markdown', 0, 0);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-VS-PRSN', 'WIKI-CHR-VS', 'personality', 'Personality', replace('Vincent is blunt to the point of cruelty. He doesn''t sugarcoat anything, and he doesn''t bother hiding his opinions, even when they''re insulting. He speaks plainly and directly, and when he raises his voice, it''s controlled and intentional, the kind of raised voice that shuts down a room. If he thinks someone is useless, he says it. If he thinks someone is slow, he says it. If he thinks someone''s wasting his time, HE SAYS IT.\n\nHe shows blatant favoritism towards his son [Jason](/jason-skank) and doesn''t care who notice. Jason''s "the only one worth a damn," even though he''s widely regarded as the biggest nuisance in the Texaria branch. Vincent excuses Jason''s failures, ignores his mistakes, and praises him in front of other agents just to make a point. [Zeke](/wiki/zeke-harborne), on the other hand, is openly fat-shamed and dismissed as "unfit," with Vincent never bothering to learn about the injury that led to it. He assumes incompetence and treats it as fact.\n\nVincent doesn''t use metaphors or coded language. He says exactly what he means, even when it''s harsh. He doesn''t care about morale, professionalism, or diplomacy. He cares about control, results, and making sure everyone knows he''s in charge.','\n',char(10)), 'markdown', 0, 1);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-VS-HSTR', 'WIKI-CHR-VS', 'history', 'History', replace('Vincent oversees the Texaria branch of the RIFT Agency, a private mercenary organization known for covert operations and strict internal hierarchy. Whether he founded the Texaria division or took control of it early on is intentionally unclear. Under his leadership, the region became known for operations that "never existed," enforced through rigid command and unforgiving expectations.\n\nHe played very little role in raising Jason or Zeke, keeping his distance until they were old enough to be evaluated. Jason was enlisted into RIFT immediately after graduating, largely because Vincent saw potential in him as a controllable asset. Zeke was dismissed early due to physical limitations, and Vincent never reconsidered the decision. His favoritism towards Jason is obvious and often used against other agents, even though Jason is widely regarded as the biggest nuisance.\n\nVery little is known about Vincent’s personal life outside of his sons. He never stayed married for long, and he openly referred to relationships as “distractions” that interfered with his work. Any details about his past were either never shared, dismissed as irrelevant, or quietly expunged from existing records, leaving most people with the impression that Vincent simply doesn’t care enough to remember them.','\n',char(10)), 'markdown', 0, 2);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-VS-ABLT', 'WIKI-CHR-VS', 'abilities', 'Abilities', 'TODO', 'markdown', 0, 3);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-VS-IDBD', 'WIKI-CHR-VS', 'He''s memorized every agent''s ID number but not a single birthday.', 0, 0);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-VS-NOFN', 'WIKI-CHR-VS', 'He refuses to use first names in meetings unless referring to Jason.', 0, 1);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-VS-TPEN', 'WIKI-CHR-VS', 'He has a habit of tapping his pen when someone''s wasting his time. Agents know it as his "patience countdown."', 0, 2);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-VS-DOOR', 'WIKI-CHR-VS', 'He tends to barge into rooms without knocking.', 0, 3);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-VS-JSON', 'WIKI-CHR-VS', 'He keeps a framed photo of Jason in his office. It''s from a disciplinary report, but he chooses to ignore that.', 0, 4);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-VS-ZEKE', 'WIKI-CHR-VS', 'He blames Zeke''s weight on his old job, saying "security guards get paid to watch TV." He''s unaware SouthPort Harbor never had security cameras due to lack-of-funding.', 0, 5);
INSERT INTO wiki_relationships (id, entry_id, related_entry_id, relation_label, notes, sort_order) VALUES ('WIKI-REL-VS-JS', 'WIKI-CHR-VS', 'WIKI-CHR-JS', 'Favorite Son / Agent', 'He''s the only one that actually does anything.', 0);
