INSERT INTO wiki_info_links (id, entry_id, label, url, is_download, nsfw_only, sort_order) VALUES ('WIKI-LINK-MA-GLRY', 'WIKI-CHR-MA', 'Gallery', '/wiki/marx-armstrong/gallery', 0, 0, 0);
INSERT INTO wiki_quotes (entry_id, quote_text, audio_url, attribution, voice_credit, nsfw_only) VALUES ('WIKI-CHR-MA', 'I-I know it sounds... strict, I guess, but rules are there kinda to stop you from, y''know, exploding, or crashing, or... whatever it is people do when they don''t listen, eh?', NULL, 'Marx', NULL, 0);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-MA-APRC', 'WIKI-CHR-MA', 'appearance', 'Appearance', replace('Marx has bright orange feathers and pale-yellow legs that make his bird-like features stand out. His eyes are a muted reddish-brown, usually sharp and attentive, though sometimes dulled from long flights and lack of sleep. He wears a pair of old flight goggled perched on his head. It is a constant accessory, both practical and sentimental.\n\nLike many birds, his wings double as arms, giving him a somewhat unique silhouette compared to others. It''s a feature he''s long since adapted to, moving fluidly and naturally with them, though it occasionally makes tasks like carrying multiple items a bit awkward. But I mean hey, at least he''s a good hugger!\n\nHe''s usually seen wearing a traditional aviator''s outfit: a heavy green-brown jacket with a fur collar, sturdy boots, and a scarf that adds both warmth and a touch of personal style. Sometimes you can see him wearing more casual clothing, like plain shirts and slacks, but it''s usually just at home or during grocery runs.','\n',char(10)), 'markdown', 0, 0);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-MA-PRSN', 'WIKI-CHR-MA', 'personality', 'Personality', replace('Marx is obedient to a fault, the kind of person who follows instructions to the letter unless they directly contradict rules he already knows or go against his moral compass. It makes him dependable in high-pressure situations, especially in aviation where precision and adherence to protocol are crucial, but it can also make him rigid where flexibility would serve better. He prefers structure over improvisation, leaning on procedure to keep both himself and others safe.\n\nThough disciplined, he isn''t cold. He''s earnest and thoughtful, with a genuine passion for aviation that bleeds into casual conversation whether anyone asked for it or not. His enthusiasm for planes and flying often borders on obsessive, but it comes from a place of deep respect for the craft rather than arrogance. Around friends, he''s mild mannered, if occasionally prone to rambling about topics like military history or aircraft models.\n\nDespite his generally easygoing nature, Marx does not handle deviation from rules well. He can come across as stubborn when pushed outside his comfort zone, and he''s especially uncomfortable with reckless behavior. Still, his loyalty to those he cares about is strong, and once he trusts someone, he''ll follow them through nearly everything, provided they''re not asking him to break the rules he holds dear.','\n',char(10)), 'markdown', 0, 1);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-MA-HSTR', 'WIKI-CHR-MA', 'history', 'History', replace('Marx grew up in [EastUnder Valley](/wiki/eastunder-valley), a quiet suburb in southeast [San Bandera](/wiki/san-bandera). From a young age, he''s shown a strong fascination with aviation, often memorizing aircraft types and flight patterns the way other kids memorized cheat codes in video games. His passion for flying wasn''t just a hobby; it became a defining part of his identity.\n\nDuring middle school, Marx was in choir classes alongside [Logan](/wiki/logan-foster), where his clear, controlled voice earned him quiet praise. While he eventually drifted away from singing, he never forgot the discipline choir demanded, a mindset that mirrored the structured world of aviation he would later embrace.\n\nAs he grew older, he pursued his love of flying with unwavering dedication, eventually training as a commercial pilot. His career became more than just work; it was the perfect outlet for his rule-driven personality. In the cockpit, checklists and procedures weren''t just suggestions, they were reassurance, the kind of order he''d always sought in life.\n\nHe eventually relocated to [Austyn](/wiki/austyn), the capital city of [Texaria](/wiki/texaria), where he continues to work as a commercial pilot. Though he''s drifted apart from some of his childhood friends, he remained defined by his passion for aviation and the strict discipline that guided him both in the air and on the ground.','\n',char(10)), 'markdown', 0, 2);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-MA-ABLT', 'WIKI-CHR-MA', 'abilities', 'Abilities', 'TODO', 'markdown', 0, 3);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-MA-VEGN', 'WIKI-CHR-MA', 'He''s vegetarian for the most part. He won''t eat meat unless it''s the ONLY option available, and even then, he probably won''t unless it''s something like bugs or other unconventional protein sources.', 0, 0);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-MA-SING', 'WIKI-CHR-MA', 'He still insists he *could* sing well from his choir days, but due to being so out of practice, he refuses to prove it.', 0, 1);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-MA-BLNT', 'WIKI-CHR-MA', 'Despite his obedience to rules, he sometimes delivers blunt, accidental roasts without even realizing how harsh they sound.', 0, 2);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-MA-CHJK', 'WIKI-CHR-MA', 'He will **NOT** be your chicken jockey.', 0, 3);
